declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;$s=require dirname(__DIR__).'/src/bootstrap.php';extract($s,EXTR_SKIP);$user=$auth->requireUser();$orgId=(int)($_GET['id']??0);$org=$db->one('SELECT * FROM organizations WHERE id=?',[$orgId]);if(!$org){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono organizacji.</div>',$user);}if(!$organizations->canManage((int)$user['id'],$orgId)){http_response_code(403);Web::page('Brak dostępu','<div class="alert danger">Brak uprawnień do organizacji.</div>',$user);}$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$action=(string)($_POST['action']??'');try{if($action==='save_member'){$from=trim((string)($_POST['valid_from']??''))?:null;$until=trim((string)($_POST['valid_until']??''))?:null;$organizations->setMember($orgId,(int)$_POST['user_id'],(string)$_POST['role'],(string)$_POST['status'],$from,$until,(int)$user['id']);}elseif($action==='remove_member')$organizations->removeMember($orgId,(int)$_POST['user_id'],(int)$user['id']);elseif($action==='assign_app'){if(!(bool)$user['is_admin'])throw new RuntimeException('Tylko administrator systemu może przenieść aplikację między tenantami.');$organizations->assignApplication($orgId,(int)$_POST['application_id'],(int)$user['id']);}Web::redirect('/admin/organizations/'.$orgId);}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}$opts='';foreach($db->all("SELECT id,name,email FROM users WHERE enabled=1 AND lifecycle_status='active' ORDER BY name")as$u)$opts.='<option value="'.(int)$u['id'].'">'.Web::e($u['name'].' — '.$u['email']).'</option>';$members='';foreach($db->all('SELECT om.*,u.name,u.email FROM organization_memberships om JOIN users u ON u.id=om.user_id WHERE om.organization_id=? ORDER BY FIELD(om.role,\'owner\',\'admin\',\'member\',\'viewer\'),u.name',[$orgId])as$m)$members.='<tr><td>'.Web::e($m['name']).'</td><td>'.Web::e($m['email']).'</td><td>'.Web::e($m['role']).'</td><td>'.Web::e($m['status']).'</td><td>'.Web::e($m['valid_until']?:'—').'</td><td><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="user_id" value="'.(int)$m['user_id'].'"><button class="danger" name="action" value="remove_member">Usuń</button></form></td></tr>';$apps='';foreach($db->all('SELECT id,name,enabled FROM applications WHERE organization_id=? AND deleted_at IS NULL ORDER BY name',[$orgId])as$a)$apps.='<li><a href="/admin/applications/'.(int)$a['id'].'">'.Web::e($a['name']).'</a> '.((bool)$a['enabled']?'':'(wyłączona)').'</li>';$assign='';if((bool)$user['is_admin']){$appOpts='';foreach($db->all('SELECT id,name FROM applications WHERE deleted_at IS NULL AND (organization_id IS NULL OR organization_id=?) ORDER BY name',[$orgId])as$a)$appOpts.='<option value="'.(int)$a['id'].'">'.Web::e($a['name']).'</option>';$assign='<form method="post" class="toolbar"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><select name="application_id">'.$appOpts.'</select><button name="action" value="assign_app">Przypisz aplikację</button></form>';}$content='<div class="page-head"><div><h1>'.Web::e($org['name']).'</h1><p>Tenant <code>'.Web::e($org['slug']).'</code></p></div><a class="button" href="/admin/organizations">Organizacje</a></div>'.$message.'<section class="card"><h2>Dodaj / zaktualizuj członka</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Użytkownik<select name="user_id">'.$opts.'</select></label><div class="form-row"><label>Rola<select name="role"><option>member</option><option>viewer</option><option>admin</option><option>owner</option></select></label><label>Status<select name="status"><option>active</option><option>pending</option><option>suspended</option><option>expired</option></select></label><label>Od<input type="datetime-local" name="valid_from"></label><label>Do<input type="datetime-local" name="valid_until"></label></div><button name="action" value="save_member" class="primary">Zapisz członkostwo</button></form></section><div class="table-wrap"><table><thead><tr><th>Użytkownik</th><th>E-mail</th><th>Rola</th><th>Status</th><th>Ważne do</th><th></th></tr></thead><tbody>'.$members.'</tbody></table></div><section class="card"><h2>Aplikacje organizacji</h2>'.$assign.'<ul>'.($apps?:'<li>Brak aplikacji.</li>').'</ul></section>';Web::page((string)$org['name'],$content,$user);
